﻿using System;
using System.Collections.Generic;

namespace SolutionOne_DataAccessLayer.Entities;

public partial class HrMenuItem
{
    public long MenuId { get; set; }

    public string MainMenu { get; set; } = null!;

    public string? ParentMenu { get; set; }

    public string? MenuIcon { get; set; }

    public string? ParentMenuIcon { get; set; }

    public string? MainMenuText { get; set; }

    public string NavigateUrl { get; set; } = null!;

    public bool? IsActive { get; set; }

    public DateTime? CrearedDt { get; set; }

    public int? DisplayOrder { get; set; }

    /// <summary>New columns added to the shared HR_MenuItems table by the sibling hr_payroll
    /// project after the two projects' databases were split/re-merged (2026-08-18). Not yet used
    /// by any logic on this side - mapped here so the entity matches the live schema, same
    /// reasoning as every other schema-drift fix this session.</summary>
    public bool? IsCustomized { get; set; }

    public bool? IsHidden { get; set; }

    public virtual ICollection<HrRolePermission> HrRolePermissions { get; set; } = new List<HrRolePermission>();

    public virtual ICollection<HrScreenDynamicQuery> HrScreenDynamicQueries { get; set; } = new List<HrScreenDynamicQuery>();
}
=== 094 ===
/*
================================================================================
094_ModuleHideFlag
================================================================================
PROBLEM
    There was no way to take a screen away from EVERYBODY. Rights are per user
    (HR_UserMenuRights), so hiding a module such as Employee meant clearing a row
    for every user and re-clearing it whenever a new user was created; and
    HR_MenuGroups.IsActive only hides a whole folder, not one screen.

    HR_MenuItems.IsActive cannot be used for this either. The markup sync in
    Payroll.master.cs (UpsertMenuItemQuery) writes `SET IsActive = 1` for every
    screen declared in the NavBar markup on EVERY non-postback page load, by
    design, so that a link can never go stale - anything hidden by clearing
    IsActive comes back by itself within one page load.

FIX
    Add HR_MenuItems.IsHidden, a flag that nothing in the markup sync touches.
    IsHidden = 1 means: dropped from the left panel for every user regardless of
    rights, and its URL refused, so it cannot be reached by typing the address.
    Maintained from Payroll/ModuleHide.aspx (reachable by direct URL only) and
    read by App_Code/ModuleHideHelper.cs.

    Defaults to 0, so applying this script changes nothing that is on screen
    today. The reader fails open when the column is absent, so an unmigrated
    database keeps its menu instead of losing it.
================================================================================
*/

SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID('dbo.HR_MenuItems') IS NULL
BEGIN
    PRINT '094: dbo.HR_MenuItems not found - skipped.';
END
ELSE IF COL_LENGTH('dbo.HR_MenuItems', 'IsHidden') IS NOT NULL
BEGIN
    PRINT '094: dbo.HR_MenuItems.IsHidden already present - skipped.';
END
ELSE
BEGIN
    ALTER TABLE dbo.HR_MenuItems
        ADD IsHidden bit NOT NULL
            CONSTRAINT DF_HR_MenuItems_IsHidden DEFAULT (0);

    PRINT '094: dbo.HR_MenuItems.IsHidden added (default 0 - nothing is hidden yet).';
END
GO

/* Belt and braces: an existing column left nullable by an earlier hand-run would
   make ISNULL(IsHidden,0) the only safe read. Normalise it instead. */
IF COL_LENGTH('dbo.HR_MenuItems', 'IsHidden') IS NOT NULL
   AND EXISTS (SELECT 1 FROM sys.columns
               WHERE object_id = OBJECT_ID('dbo.HR_MenuItems')
                 AND name = 'IsHidden'
                 AND is_nullable = 1)
BEGIN
    UPDATE dbo.HR_MenuItems SET IsHidden = 0 WHERE IsHidden IS NULL;
    ALTER TABLE dbo.HR_MenuItems ALTER COLUMN IsHidden bit NOT NULL;
    PRINT '094: dbo.HR_MenuItems.IsHidden normalised to NOT NULL.';
END
GO

PRINT '094_ModuleHideFlag complete';
GO

