using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

/// <summary>
/// Module Hide: a per-screen kill switch that overrides rights.
///
/// When a screen is hidden it disappears from the left panel for EVERYONE, whatever
/// HR_UserMenuRights says, and its URL stops working - so it cannot be reached by
/// typing the address either. Maintained from Payroll/ModuleHide.aspx, which is
/// deliberately not linked from anywhere.
///
/// WHY A NEW COLUMN AND NOT HR_MenuItems.IsActive: the markup sync in
/// Payroll.master.cs (UpsertMenuItemQuery) writes `SET IsActive = 1` for every screen
/// declared in the NavBar markup on every non-postback page load, on purpose, so a link
/// can never go stale. Anything hidden by clearing IsActive would therefore come back by
/// itself within one page load. IsHidden is never touched by that sync.
///
/// EVERYTHING HERE FAILS OPEN. If HR_MenuItems.IsHidden does not exist yet - the
/// migration has not reached this database, and the runner is known to stall (see the
/// solutionone-sql rules) - the queries below throw, one row is written to HR_ErrorLog,
/// and NOTHING is hidden. The alternative, adding the predicate to the menu SQL itself,
/// would make an unmigrated database render an EMPTY left panel.
/// </summary>
public static class ModuleHideHelper
{
    /// <summary>
    /// How long a cached snapshot is trusted. The set is also invalidated explicitly the
    /// moment ModuleHide.aspx saves, so on a single server a change takes effect at once;
    /// this is only the backstop for another process having written the flag.
    /// </summary>
    private const int CacheSeconds = 30;

    private static readonly object Sync = new object();
    private static HashSet<string> _hiddenModules;   // HR_MenuItems.MainMenu (the screen Name)
    private static HashSet<string> _blockedFiles;    // lower-case file names, no path, no query
    private static DateTime _loadedUtc;
    private static bool _schemaWarningLogged;

    /// <summary>
    /// Pages that must never be blocked no matter what the table says, so a mistake here
    /// can always be undone: this screen itself, the dashboard it redirects to, and the
    /// sign-in flow.
    /// </summary>
    private static readonly HashSet<string> NeverBlocked =
        new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "modulehide.aspx", "home.aspx", "default.aspx", "signin.aspx", "register.aspx", "errorpage.aspx"
        };

    /// <summary>True when this screen (HR_MenuItems.MainMenu) is hidden from every user.</summary>
    public static bool IsModuleHidden(string mainMenu)
    {
        if (string.IsNullOrEmpty(mainMenu))
            return false;

        HashSet<string> hidden = EnsureLoaded().Modules;
        return hidden.Count > 0 && hidden.Contains(mainMenu.Trim());
    }

    /// <summary>
    /// The hidden screen names, as one snapshot. Callers that filter a whole menu should
    /// take this once rather than calling IsModuleHidden per row.
    /// </summary>
    public static HashSet<string> HiddenModules()
    {
        return EnsureLoaded().Modules;
    }

    /// <summary>
    /// True when this request is for a page that only hidden menu entries point at.
    ///
    /// The rule is "EVERY menu entry pointing at this file is hidden", not "any", and it
    /// matters: report items all share ReportViewer.aspx with a different query string, so
    /// an "any" rule would take every report down the moment one of them was hidden.
    /// Matching is on the FILE NAME, never a substring of the URL - a substring test is
    /// what once made TaskDashboard.aspx match Dashboard.aspx.
    /// </summary>
    public static bool IsPathBlocked(string appRelativePath)
    {
        if (string.IsNullOrWhiteSpace(appRelativePath))
            return false;

        string file = FileNameOf(appRelativePath);
        if (file.Length == 0 || !file.EndsWith(".aspx", StringComparison.OrdinalIgnoreCase))
            return false;

        if (NeverBlocked.Contains(file))
            return false;

        HashSet<string> blocked = EnsureLoaded().Files;
        return blocked.Count > 0 && blocked.Contains(file);
    }

    /// <summary>Drops the cached snapshot so the next read sees what was just saved.</summary>
    public static void Invalidate()
    {
        lock (Sync)
        {
            _hiddenModules = null;
            _blockedFiles = null;
            _loadedUtc = DateTime.MinValue;
        }
    }

    // ------------------------------------------------------------------ the cache --

    private struct Snapshot
    {
        public HashSet<string> Modules;
        public HashSet<string> Files;
    }

    private static Snapshot EnsureLoaded()
    {
        lock (Sync)
        {
            if (_hiddenModules != null && (DateTime.UtcNow - _loadedUtc).TotalSeconds < CacheSeconds)
                return new Snapshot { Modules = _hiddenModules, Files = _blockedFiles };

            HashSet<string> modules = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            HashSet<string> files = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            try
            {
                // Every row, hidden or not: the file-level rule needs to know whether a
                // NON-hidden entry also points at the same page.
                // ASP.NET rows only: an Angular path like '/employees/list' reduces to the
                // file name "list" here and could block an unrelated page of that name.
                string query = @"
                    SELECT ISNULL(MainMenu, '') AS MainMenu,
                           ISNULL(NavigateUrl, '') AS NavigateUrl,
                           CAST(ISNULL(IsHidden, 0) AS int) AS IsHidden
                    FROM   HR_MenuItems mi
                    WHERE  " + MenuScope.AspNetOnly("mi");

                Dictionary<string, bool> allHiddenByFile = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);

                using (SqlConnection conn = new SqlConnection(DbConnectionFactory.GetConnectionString()))
                using (SqlCommand cmd = new SqlCommand(query, conn))
                {
                    conn.Open();
                    using (SqlDataReader reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            bool isHidden = Convert.ToInt32(reader["IsHidden"]) == 1;
                            string mainMenu = Convert.ToString(reader["MainMenu"]).Trim();
                            string file = FileNameOf(Convert.ToString(reader["NavigateUrl"]));

                            if (isHidden && mainMenu.Length > 0)
                                modules.Add(mainMenu);

                            if (file.Length == 0)
                                continue;

                            bool everyEntryHidden;
                            allHiddenByFile[file] = allHiddenByFile.TryGetValue(file, out everyEntryHidden)
                                ? everyEntryHidden && isHidden
                                : isHidden;
                        }
                    }
                }

                foreach (KeyValuePair<string, bool> entry in allHiddenByFile)
                {
                    if (entry.Value)
                        files.Add(entry.Key);
                }
            }
            catch (Exception ex)
            {
                // Fail open - see the class comment. Logged once per AppDomain so a
                // missing migration is diagnosable without filling HR_ErrorLog.
                modules.Clear();
                files.Clear();

                if (!_schemaWarningLogged)
                {
                    _schemaWarningLogged = true;
                    ErrorLogHelper.Log(ex, "ModuleHideHelper.Load");
                }
            }

            _hiddenModules = modules;
            _blockedFiles = files;
            _loadedUtc = DateTime.UtcNow;

            return new Snapshot { Modules = modules, Files = files };
        }
    }

    /// <summary>File name only: no folder, no query string, lower case.</summary>
    private static string FileNameOf(string navigateUrl)
    {
        if (string.IsNullOrWhiteSpace(navigateUrl))
            return string.Empty;

        string url = navigateUrl.Trim().Replace('\\', '/');

        int query = url.IndexOf('?');
        if (query >= 0)
            url = url.Substring(0, query);

        int hash = url.IndexOf('#');
        if (hash >= 0)
            url = url.Substring(0, hash);

        int slash = url.LastIndexOf('/');
        if (slash >= 0)
            url = url.Substring(slash + 1);

        return url.Trim().ToLowerInvariant();
    }

    // ------------------------------------------------------------- admin screen --

    /// <summary>
    /// Every screen the menu knows about, with its current hide state and how many users
    /// have been granted it - so the admin can see what a hide is overriding.
    ///
    /// Both filters are applied in the SELECT rather than on the returned table, so paging
    /// and sorting stay inside the filtered set instead of paging the whole list and then
    /// thinning each page.
    /// </summary>
    /// <param name="search">Matched against module name, screen name, folder and page. Null/empty = everything.</param>
    /// <param name="hidden">true = hidden only, false = visible only, null = both.</param>
    public static DataTable LoadModules(string search, bool? hidden)
    {
        string query = @"
            SELECT mi.MenuID,
                   mi.MainMenu,
                   ISNULL(NULLIF(LTRIM(RTRIM(mi.MainMenuText)), ''), mi.MainMenu) AS ModuleName,
                   ISNULL(NULLIF(LTRIM(RTRIM(mi.ParentMenu)), ''), '(none)')      AS ParentMenu,
                   ISNULL(mi.NavigateUrl, '')                                     AS NavigateUrl,
                   CAST(ISNULL(mi.IsHidden, 0) AS bit)                            AS IsHidden,
                   CASE WHEN ISNULL(mi.IsHidden, 0) = 1 THEN 'Hidden' ELSE 'Visible' END AS HideText,
                   (SELECT COUNT(*)
                    FROM   HR_UserMenuRights ur
                    WHERE  ur.MenuID = mi.MenuID
                      AND  ur.IsMenuRights = 1
                      AND  ISNULL(ur.IsActive, 1) = 1)                            AS RightsCount
            FROM   HR_MenuItems mi
            WHERE  ISNULL(mi.IsActive, 1) = 1
              AND  " + MenuScope.AspNetOnly("mi") + @"
              AND  (@Search = ''
                    OR mi.MainMenu                     LIKE '%' + @Search + '%' ESCAPE '\'
                    OR ISNULL(mi.MainMenuText, '')     LIKE '%' + @Search + '%' ESCAPE '\'
                    OR ISNULL(mi.ParentMenu, '')       LIKE '%' + @Search + '%' ESCAPE '\'
                    OR ISNULL(mi.NavigateUrl, '')      LIKE '%' + @Search + '%' ESCAPE '\')
              AND  (@Hidden IS NULL OR CAST(ISNULL(mi.IsHidden, 0) AS int) = @Hidden)
            ORDER  BY ISNULL(NULLIF(LTRIM(RTRIM(mi.ParentMenu)), ''), '(none)'),
                      ISNULL(NULLIF(LTRIM(RTRIM(mi.MainMenuText)), ''), mi.MainMenu)";

        DataTable table = new DataTable();
        using (SqlConnection conn = new SqlConnection(DbConnectionFactory.GetConnectionString()))
        using (SqlDataAdapter da = new SqlDataAdapter(query, conn))
        {
            da.SelectCommand.Parameters.Add("@Search", SqlDbType.NVarChar, 400).Value =
                EscapeLike(search);
            da.SelectCommand.Parameters.Add("@Hidden", SqlDbType.Int).Value =
                hidden.HasValue ? (hidden.Value ? 1 : 0) : (object)DBNull.Value;
            da.Fill(table);
        }

        return table;
    }

    /// <summary>
    /// Neutralises the LIKE wildcards so a typed % or _ matches itself. Paired with
    /// ESCAPE '\' in the query above - without it, typing "_" would match every character
    /// and the filter would look broken.
    /// </summary>
    private static string EscapeLike(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return string.Empty;

        return value.Trim()
                    .Replace("\\", "\\\\")
                    .Replace("%", "\\%")
                    .Replace("_", "\\_")
                    .Replace("[", "\\[");
    }

    /// <summary>
    /// Sets or clears the hide flag on one screen. Returns the screen's caption so the
    /// caller can name it in the confirmation; null when the row was not found.
    /// </summary>
    public static string SetHidden(long menuId, bool hidden, long userId)
    {
        string query = @"
            UPDATE HR_MenuItems
            SET    IsHidden = @IsHidden
            WHERE  MenuID = @MenuID
              AND  " + MenuScope.AspNetOnly("HR_MenuItems") + @";

            SELECT ISNULL(NULLIF(LTRIM(RTRIM(MainMenuText)), ''), MainMenu) AS ModuleName
            FROM   HR_MenuItems
            WHERE  MenuID = @MenuID;";

        string moduleName = null;

        using (SqlConnection conn = new SqlConnection(DbConnectionFactory.GetConnectionString()))
        using (SqlCommand cmd = new SqlCommand(query, conn))
        {
            cmd.Parameters.Add("@IsHidden", SqlDbType.Bit).Value = hidden;
            cmd.Parameters.Add("@MenuID", SqlDbType.BigInt).Value = menuId;
            conn.Open();

            object result = cmd.ExecuteScalar();
            if (result != null && result != DBNull.Value)
                moduleName = Convert.ToString(result);
        }

        // The left panel and the URL guard both read the cached snapshot, so it has to go
        // now rather than in CacheSeconds' time.
        Invalidate();

        return moduleName;
    }
}

