                    _schemaWarningLogged = true;
                    ErrorLogHelper.Log(ex, "ModuleHideHelper.Load");
                }
            }

            _hiddenModules = modules;
            _blockedFiles = files;
            _loadedUtc = DateTime.UtcNow;

            return new Snapshot { Modules = modules, Files = files };
        }
    }

    /// <summary>File name only: no folder, no query string, lower case.</summary>
    private static string FileNameOf(string navigateUrl)
    {
        if (string.IsNullOrWhiteSpace(navigateUrl))
            return string.Empty;

        string url = navigateUrl.Trim().Replace('\\', '/');

        int query = url.IndexOf('?');
        if (query >= 0)
            url = url.Substring(0, query);

        int hash = url.IndexOf('#');
        if (hash >= 0)
            url = url.Substring(0, hash);

        int slash = url.LastIndexOf('/');
        if (slash >= 0)
            url = url.Substring(slash + 1);

        return url.Trim().ToLowerInvariant();
    }

    // ------------------------------------------------------------- admin screen --

    /// <summary>
    /// Every screen the menu knows about, with its current hide state and how many users
    /// have been granted it - so the admin can see what a hide is overriding.
    ///
    /// Both filters are applied in the SELECT rather than on the returned table, so paging
    /// and sorting stay inside the filtered set instead of paging the whole list and then
    /// thinning each page.
    /// </summary>
    /// <param name="search">Matched against module name, screen name, folder and page. Null/empty = everything.</param>
    /// <param name="hidden">true = hidden only, false = visible only, null = both.</param>
    public static DataTable LoadModules(string search, bool? hidden)
    {
        string query = @"
            SELECT mi.MenuID,
                   mi.MainMenu,
                   ISNULL(NULLIF(LTRIM(RTRIM(mi.MainMenuText)), ''), mi.MainMenu) AS ModuleName,
                   ISNULL(NULLIF(LTRIM(RTRIM(mi.ParentMenu)), ''), '(none)')      AS ParentMenu,
                   ISNULL(mi.NavigateUrl, '')                                     AS NavigateUrl,
                   CAST(ISNULL(mi.IsHidden, 0) AS bit)                            AS IsHidden,
                   CASE WHEN ISNULL(mi.IsHidden, 0) = 1 THEN 'Hidden' ELSE 'Visible' END AS HideText,
                   (SELECT COUNT(*)
                    FROM   HR_UserMenuRights ur
                    WHERE  ur.MenuID = mi.MenuID
                      AND  ur.IsMenuRights = 1
                      AND  ISNULL(ur.IsActive, 1) = 1)                            AS RightsCount
            FROM   HR_MenuItems mi
            WHERE  ISNULL(mi.IsActive, 1) = 1
              AND  " + MenuScope.AspNetOnly("mi") + @"
              AND  (@Search = ''
                    OR mi.MainMenu                     LIKE '%' + @Search + '%' ESCAPE '\'
                    OR ISNULL(mi.MainMenuText, '')     LIKE '%' + @Search + '%' ESCAPE '\'
                    OR ISNULL(mi.ParentMenu, '')       LIKE '%' + @Search + '%' ESCAPE '\'
                    OR ISNULL(mi.NavigateUrl, '')      LIKE '%' + @Search + '%' ESCAPE '\')
              AND  (@Hidden IS NULL OR CAST(ISNULL(mi.IsHidden, 0) AS int) = @Hidden)
            ORDER  BY ISNULL(NULLIF(LTRIM(RTRIM(mi.ParentMenu)), ''), '(none)'),
                      ISNULL(NULLIF(LTRIM(RTRIM(mi.MainMenuText)), ''), mi.MainMenu)";

        DataTable table = new DataTable();
        using (SqlConnection conn = new SqlConnection(DbConnectionFactory.GetConnectionString()))
        using (SqlDataAdapter da = new SqlDataAdapter(query, conn))
        {
            da.SelectCommand.Parameters.Add("@Search", SqlDbType.NVarChar, 400).Value =
                EscapeLike(search);
            da.SelectCommand.Parameters.Add("@Hidden", SqlDbType.Int).Value =
                hidden.HasValue ? (hidden.Value ? 1 : 0) : (object)DBNull.Value;
            da.Fill(table);
        }

        return table;
    }

    /// <summary>
    /// Neutralises the LIKE wildcards so a typed % or _ matches itself. Paired with
    /// ESCAPE '\' in the query above - without it, typing "_" would match every character
    /// and the filter would look broken.
    /// </summary>
    private static string EscapeLike(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return string.Empty;

        return value.Trim()
                    .Replace("\\", "\\\\")
                    .Replace("%", "\\%")
                    .Replace("_", "\\_")
                    .Replace("[", "\\[");
    }

    /// <summary>
    /// Sets or clears the hide flag on one screen. Returns the screen's caption so the
    /// caller can name it in the confirmation; null when the row was not found.
    /// </summary>
    public static string SetHidden(long menuId, bool hidden, long userId)
    {
        string query = @"
            UPDATE HR_MenuItems
            SET    IsHidden = @IsHidden
            WHERE  MenuID = @MenuID
              AND  " + MenuScope.AspNetOnly("HR_MenuItems") + @";

            SELECT ISNULL(NULLIF(LTRIM(RTRIM(MainMenuText)), ''), MainMenu) AS ModuleName
            FROM   HR_MenuItems
            WHERE  MenuID = @MenuID;";

        string moduleName = null;

        using (SqlConnection conn = new SqlConnection(DbConnectionFactory.GetConnectionString()))
        using (SqlCommand cmd = new SqlCommand(query, conn))
        {
            cmd.Parameters.Add("@IsHidden", SqlDbType.Bit).Value = hidden;
            cmd.Parameters.Add("@MenuID", SqlDbType.BigInt).Value = menuId;
            conn.Open();

            object result = cmd.ExecuteScalar();
            if (result != null && result != DBNull.Value)
                moduleName = Convert.ToString(result);
        }

        // The left panel and the URL guard both read the cached snapshot, so it has to go
        // now rather than in CacheSeconds' time.
        Invalidate();

        return moduleName;
    }
}

