/// <summary>
/// HR_MenuItems / HR_UserMenuRights are shared with the Angular app. Its rows carry
/// router paths in NavigateUrl ('/employees/list'); ours carry pages ('Employee.aspx').
/// Every query here that reads or writes menu rows must stay on our side of that line,
/// otherwise Angular screens show up in the left panel, the rights tree and the layout
/// screen, and the markup sync would de-activate them.
///
/// A row is Angular's when its URL starts with '/' and names no .aspx page - so an
/// ASP.NET row stored as '/Payroll/X.aspx' still counts as ours.
/// </summary>
public static class MenuScope
{
    /// <summary>
    /// SQL predicate (no leading AND) that keeps only ASP.NET rows of an HR_MenuItems
    /// alias, e.g. "WHERE mi.IsActive = 1 AND " + MenuScope.AspNetOnly("mi").
    /// </summary>
    public static string AspNetOnly(string alias)
    {
        string url = alias + ".NavigateUrl";
        return "(ISNULL(LTRIM(" + url + "), '') NOT LIKE '/%' OR " + url + " LIKE '%.aspx%')";
    }

    /// <summary>Same rule applied in C# to a NavigateUrl value.</summary>
    public static bool IsAspNetUrl(string navigateUrl)
    {
        string url = (navigateUrl ?? string.Empty).Trim();
        return !url.StartsWith("/") || url.IndexOf(".aspx", System.StringComparison.OrdinalIgnoreCase) >= 0;
    }
}

