﻿using Dapper;
using Microsoft.Extensions.Logging;
using SolutionOne_Core.CommonModels.Menu;
using SolutionOne_DataAccessLayer.Repositories.Common.Implementation;
using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
using SolutionOne_DataAccessLayer.Repositories.MenuRights.Interface;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace SolutionOne_DataAccessLayer.Repositories.MenuRights.Implementation
{
	/// <summary>
	/// The screen catalog (HR_MenuItems) and the menu folder tree. Deliberately NOT here: any per-user
	/// menu rights. HR_UserMenuRights belongs to hr_payroll and this app neither reads nor writes it -
	/// what a user may open here comes only from the RBAC tables (roles, HR_UserScreenAccess, overrides).
	/// </summary>
	public class MenuHandleRepository(
		IDapperContext ctx,
		IDapperRepository rep,
		ILogger<MenuHandleRepository> lg
		) : IMenuHandleRepository
	{
		private readonly IDapperRepository _repo = rep;
		private readonly IDapperContext _ctxt = ctx;
		private readonly ILogger<MenuHandleRepository> _logger = lg;

		/// <summary>
		/// HR_MenuItems is shared with the sibling hr_payroll project (an ASP.NET WebForms app).
		/// Its rows are distinguished purely by NavigateUrl - every payroll menu item's URL ends
		/// in ".aspx" (optionally with a query string, e.g. "ReportViewer.aspx?ID=1"); every one
		/// of ours is a route path (e.g. "/recruitment/requisition") or empty for a leaf-less
		/// heading. A NULL/empty NavigateUrl is also excluded - payroll has at least one such row
		/// (a "Recruitment Portal" placeholder heading with no route) that isn't navigable from
		/// this app either. Apply this to every query that reads the menu catalog on this side, so
		/// this app never displays, resolves rights for, or (in SyncFrontendMenusAsync) disables
		/// the other project's rows. Written unqualified - only use this against queries where
		/// HR_MenuItems is unaliased (or is the only table with a NavigateUrl column in scope);
		/// queries that alias HR_MenuItems (e.g. "mi") spell the same condition out with that
		/// prefix instead, to avoid ambiguous-column risk.
		/// </summary>
		private const string NonPayrollMenuFilterSql =
			"AND NavigateUrl IS NOT NULL AND NavigateUrl <> '' AND NavigateUrl NOT LIKE '%.aspx%'";

		public async Task<List<ListAllMenu>> FetchAllMenu(string? parentMenu = null)
		{
			var sql = new StringBuilder(@"SELECT
                    MenuId,
                    MainMenu,
                    ParentMenu,
                    MenuIcon,
                    ParentMenuIcon,
                    MainMenuText,
                    NavigateUrl,
                    IsActive,
                    DisplayOrder
                FROM HR_MenuItems
                WHERE 1 = 1 AND IsActive = 1
                  " + NonPayrollMenuFilterSql + @"
            ");

			var parameters = new DynamicParameters();

			if (!string.IsNullOrWhiteSpace(parentMenu))
			{
				sql.AppendLine("AND ParentMenu LIKE '%' + @parentMenu + '%'");
				parameters.Add("parentMenu", parentMenu.Trim());
			}

			var result = await _repo.QueryAsync<ListAllMenu>(
				sql.ToString(),
				parameters);

			return result.ToList();
		}

		/// <summary>
		/// The folder tree the left navigation groups its screens into, in SortPath order so a
		/// parent is always read before its children.
		///
		/// De-activated folders are returned rather than filtered out in SQL. The caller has to
		/// be able to tell "this folder is hidden on purpose" from "this folder does not exist":
		/// screens are matched to folders by NAME, so a hidden folder whose name never reaches
		/// the caller has its screens rescued into a flat group of their own - which is exactly
		/// the bug un-ticking Active is meant to avoid. This mirrors hr_payroll's
		/// Payroll.master.cs MenuFolderQuery, deliberately.
		///
		/// HR_MenuGroups / vw_HR_MenuGroupTree are not present in every tenant database. A
		/// missing view is a "no tree configured" answer, not an error - the caller then falls
		/// back to grouping by HR_MenuItems.ParentMenu alone, which is what this app did before
		/// the tree existed.
		/// </summary>
		public async Task<List<MenuGroupNode>> FetchMenuGroupTreeAsync()
		{
			try
			{
				var exists = await _repo.QueryFirstOrDefaultAsync<int?>(
					"SELECT 1 WHERE OBJECT_ID('vw_HR_MenuGroupTree') IS NOT NULL", null);

				if (exists is null) return new List<MenuGroupNode>();

				var sql = @"
                SELECT
                    GroupID       AS GroupId,
                    ParentGroupID AS ParentGroupId,
                    GroupName,
                    GroupIcon,
                    NodeLevel,
                    IsActive,
                    SortPath,
                    DisplayOrder
                FROM vw_HR_MenuGroupTree
                ORDER BY SortPath";

				var result = await _repo.QueryAsync<MenuGroupNode>(sql, null);
				return result.ToList();
			}
			catch (Exception e)
			{
				// An unreadable menu tree must not take the login down with it - the navigation
				// degrades to flat ParentMenu grouping instead of disappearing.
				_logger.LogError(e, "Error reading the menu group tree; falling back to flat menu grouping");
				return new List<MenuGroupNode>();
			}
		}

		public async Task<List<ListAllUsers>> SearchUsers(string? searchPhrase = null)
		{
			try
			{
				var sql = new StringBuilder(@"SELECT
                    em.EmployeeMasterID,
                    um.UserName,
                    um.Code as UserCode,
                    em.Code as EmpCode,
                    em.FirstName,
                    em.LastName,
                    em.Address,
                    em.Gender,
                    em.MobileNo,
                    em.AadharCardNo,
                    em.IsHradmin,
                    em.ReportingPersonId,
                    um.UserMasterID,
                    em.DepartmentMasterId,
                    em.DesignationMasterId,
                    em.ShiftMasterId,
                    em.CategoryMasterId,
                    em.BranchMasterId,
                    em.CompanyMasterId,
                    em.FormId,
                    um.Role,
                    em.Email
                FROM HR_EmployeeMaster em
                INNER JOIN HR_UserMaster um on em.EmployeeMasterID = um.EmployeeMasterID
                WHERE 1 = 1
                ");

				var parameters = new DynamicParameters();

				if (!string.IsNullOrWhiteSpace(searchPhrase))
				{
					sql.AppendLine(@"AND (
                        em.FirstName LIKE '%' + @searchPhrase + '%' OR
                        em.LastName LIKE '%' + @searchPhrase + '%' OR
                        um.Code LIKE '%' + @searchPhrase + '%' OR
                        em.AadharCardNo LIKE '%' + @searchPhrase + '%'
                    )");
					parameters.Add("searchPhrase", searchPhrase.Trim());
				}

				var result = await _repo.QueryAsync<ListAllUsers>(sql.ToString(), parameters);
				return result.ToList();
			}
			catch (Exception e)
			{
				_logger.LogError(e, "Error searching users");
				throw;
			}
		}

		public async Task<List<ListAllUsers>> GetUsersByIds(List<long> ids)
		{
			if (ids == null || !ids.Any()) return new List<ListAllUsers>();
			try
			{
				var sql = @"SELECT
                    em.EmployeeMasterId,
                    um.UserName,
                    um.Code as UserCode,
                    em.Code as EmpCode,
                    em.FirstName,
                    em.LastName,
                    em.Address,
                    em.Gender,
                    em.MobileNo,
                    em.AadharCardNo,
                    em.IsHradmin,
                    em.ReportingPersonId,
                    em.UserMasterId,
                    em.DepartmentMasterId,
                    em.DesignationMasterId,
                    em.ShiftMasterId,
                    em.CategoryMasterId,
                    em.BranchMasterId,
                    em.CompanyMasterId,
                    em.FormId,
                    um.Role,
                    em.Email
                FROM HR_EmployeeMaster em
                INNER JOIN HR_UserMaster um on em.EmployeeMasterID = um.EmployeeMasterID
                WHERE um.UserMasterID IN @ids
                ";

				var parameters = new DynamicParameters();
				parameters.Add("ids", ids);

				var result = await _repo.QueryAsync<ListAllUsers>(sql, parameters);
				return result.ToList();
			}
			catch (Exception e)
			{
				_logger.LogError(e, "Error fetching users by ids");
				throw;
			}
		}

		public async Task<long?> GetMenuIdByNavigateUrl(string navigateUrl)
		{
			try
			{
				var sql = $"""
					SELECT TOP 1 MenuID
					FROM HR_MenuItems
					WHERE NavigateUrl = @NavigateUrl
					{NonPayrollMenuFilterSql};
					""";

				return await _repo.QueryFirstOrDefaultAsync<long?>(sql, new { NavigateUrl = navigateUrl });
			}
			catch (Exception e)
			{
				_logger.LogError(e, "Error resolving MenuID for NavigateUrl {NavigateUrl}", navigateUrl);
				throw;
			}
		}

		public async Task<int> SyncFrontendMenusAsync(List<ListAllMenu> flattenedMenus)
		{
			await _ctxt.BeginTransactionAsync();
			try
			{
				// Scoped to this app's own rows only - HR_MenuItems is now shared with the sibling
				// hr_payroll project. An unscoped "UPDATE ... SET IsActive = 0" here previously
				// disabled EVERY row in the table on every sync, including hr_payroll's, and is the
				// confirmed cause of this project's own recruitment menu rows turning up
				// IsActive = 0 in the shared database after hr_payroll ran its own equivalent sync.
				var disableSql = $"UPDATE HR_MenuItems SET IsActive = 0 WHERE 1 = 1 {NonPayrollMenuFilterSql}";
				await _repo.ExecuteAsync(disableSql, null);

				var insertSql = @"
                                        INSERT INTO HR_MenuItems (MainMenu, ParentMenu, MenuIcon, ParentMenuIcon, MainMenuText, NavigateUrl, IsActive, DisplayOrder)
                                        VALUES (@MainMenu, @ParentMenu, @MenuIcon, @ParentMenuIcon, @MainMenuText, @NavigateUrl, 1, @DisplayOrder)
                                ";

				var rowsAffected = await _repo.ExecuteAsync(insertSql, flattenedMenus);
				await _ctxt.CommitAsync();
				return rowsAffected;
			}
			catch (Exception e)
			{
				_logger.LogError(e, "Error syncing frontend menus");
				await _ctxt.RollbackAsync();
				throw;
			}
		}
	}
}

