﻿using Microsoft.Extensions.Logging;
using SolutionOne_DataAccessLayer.Repositories.MenuRights.Interface;
using SolutionOne_BusinessLogicLayer.Services.MenuRights.Interface;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.CommonModels.Menu;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Threading.Tasks;

namespace SolutionOne_BusinessLogicLayer.Services.MenuRights.Implementation
{
	/// <summary>
	/// The screen catalog and menu folder tree. Per-user menu rights are NOT handled here:
	/// HR_UserMenuRights belongs to hr_payroll and this app never reads or writes it. What a user may
	/// open comes from the RBAC services (roles, direct screen access, overrides).
	/// </summary>
	public class MenuHandleService(
		IMenuHandleRepository menuHandleRepo,
		ILogger<MenuHandleService> logger) : IMenuHandleService
	{
		private readonly IMenuHandleRepository _menuHandleRepo = menuHandleRepo;
		private readonly ILogger<MenuHandleService> _logger = logger;

		public async Task<ResponseModel<List<ListAllMenu>>> FetchAllMenu(string? parentMenu = null)
		{
			var res = new ResponseModel<List<ListAllMenu>>();

			try
			{
				var data = await _menuHandleRepo.FetchAllMenu(parentMenu);

				if (data == null || !data.Any())
				{
					res.IsSuccess = true;
					res.Status = HttpStatusCode.OK;
					res.Message = "No menu items found.";
					res.Data = new List<ListAllMenu>();
					return res;
				}

				res.IsSuccess = true;
				res.Status = HttpStatusCode.OK;
				res.Message = "Menu items fetched successfully.";
				res.Data = data;
			}
			catch (Exception ex)
			{
				_logger.LogError(ex, "Error fetching all menus");

				res.IsSuccess = false;
				res.Status = HttpStatusCode.InternalServerError;
				res.Message = $"Error fetching menus: {ex.Message}";
			}

			return res;
		}

		/// <summary>
		/// The folder tree the navigation groups screens into. An empty list is a valid answer -
		/// it means this database has no HR_MenuGroups tree, and the client then falls back to
		/// grouping by HR_MenuItems.ParentMenu on its own.
		/// </summary>
		public async Task<ResponseModel<List<MenuGroupNode>>> FetchMenuGroups()
		{
			var res = new ResponseModel<List<MenuGroupNode>>();

			try
			{
				var data = await _menuHandleRepo.FetchMenuGroupTreeAsync();

				res.IsSuccess = true;
				res.Status = HttpStatusCode.OK;
				res.Data = data ?? new List<MenuGroupNode>();
				res.Message = res.Data.Count == 0
					? "No menu groups configured."
					: "Menu groups fetched successfully.";
			}
			catch (Exception ex)
			{
				_logger.LogError(ex, "Error fetching menu groups");

				res.IsSuccess = false;
				res.Status = HttpStatusCode.InternalServerError;
				res.Message = $"Error fetching menu groups: {ex.Message}";
			}

			return res;
		}

		public async Task<ResponseModel<List<ListAllUsers>>> SearchUsers(string? searchPhrase = null)
		{
			var res = new ResponseModel<List<ListAllUsers>>();

			try
			{
				var data = await _menuHandleRepo.SearchUsers(searchPhrase);

				if (data == null || !data.Any())
				{
					res.IsSuccess = true;
					res.Status = HttpStatusCode.OK;
					res.Message = "No users matched the search phrase.";
					res.Data = new List<ListAllUsers>();
					return res;
				}

				res.IsSuccess = true;
				res.Status = HttpStatusCode.OK;
				res.Message = "Users searched successfully.";
				res.Data = data;
			}
			catch (Exception ex)
			{
				_logger.LogError(ex, "Error searching users");

				res.IsSuccess = false;
				res.Status = HttpStatusCode.InternalServerError;
				res.Message = $"Error searching users: {ex.Message}";
			}

			return res;
		}

		public async Task<ResponseModel<List<ListAllUsers>>> GetUsersByIds(List<long> ids)
		{
			var res = new ResponseModel<List<ListAllUsers>>();

			try
			{
				if (ids == null || !ids.Any())
				{
					res.IsSuccess = true;
					res.Status = HttpStatusCode.OK;
					res.Message = "No IDs provided.";
					res.Data = new List<ListAllUsers>();
					return res;
				}

				var data = await _menuHandleRepo.GetUsersByIds(ids);

				res.IsSuccess = true;
				res.Status = HttpStatusCode.OK;
				res.Message = "Users fetched successfully.";
				res.Data = data;
			}
			catch (Exception ex)
			{
				_logger.LogError(ex, "Error fetching users by IDs");

				res.IsSuccess = false;
				res.Status = HttpStatusCode.InternalServerError;
				res.Message = $"Error: {ex.Message}";
			}

			return res;
		}

		// Following are the functions that do not return to any controllers but to other services
		// that depend on this.

		public async Task<long?> GetMenuIdByNavigateUrl(string navigateUrl)
		{
			try
			{
				_logger.LogCritical($"{navigateUrl}");
				return await _menuHandleRepo.GetMenuIdByNavigateUrl(navigateUrl);
			}
			catch (Exception ex)
			{
				_logger.LogError(ex, "Error resolving MenuID for NavigateUrl {NavigateUrl}", navigateUrl);
				throw new InvalidOperationException("Error resolving menu: " + ex.Message);
			}
		}

		public async Task<ResponseModel<int>> SyncMenusFromFrontend(List<FrontendMenuSyncDto> frontendMenus)
		{
			var res = new ResponseModel<int>();
			try
			{
				var flatList = new List<ListAllMenu>();
				int displayOrder = 1;

				foreach (var parent in frontendMenus)
				{
					if (parent.items != null && parent.items.Any())
					{
						foreach (var item in parent.items)
						{
							flatList.Add(new ListAllMenu
							{
								MainMenu = item.label,
								ParentMenu = parent.label,
								MenuIcon = item.icon ?? "",
								ParentMenuIcon = parent.icon ?? "",
								MainMenuText = item.label.Replace(" ", ""),
								NavigateUrl = item.routeLink ?? item.url ?? "",
								DisplayOrder = displayOrder++
							});
						}
					}
					else
					{
						flatList.Add(new ListAllMenu
						{
							MainMenu = parent.label,
							ParentMenu = "",
							MenuIcon = parent.icon ?? "",
							ParentMenuIcon = "",
							MainMenuText = parent.label.Replace(" ", ""),
							NavigateUrl = parent.routeLink ?? parent.url ?? "",
							DisplayOrder = displayOrder++
						});
					}
				}

				int rowsAffected = await _menuHandleRepo.SyncFrontendMenusAsync(flatList);

				res.IsSuccess = true;
				res.Status = HttpStatusCode.OK;
				res.Message = $"Successfully synced {rowsAffected} menus.";
				res.Data = rowsAffected;
			}
			catch (Exception ex)
			{
				_logger.LogError(ex, "Error syncing frontend menus");
				res.IsSuccess = false;
				res.Status = HttpStatusCode.InternalServerError;
				res.Message = $"Sync failed: {ex.Message}";
			}

			return res;
		}
	}
}

