using Dapper;
using SolutionOne_Core.CommonModels.RBAC;
using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
using SolutionOne_DataAccessLayer.Repositories.RBAC.Interface;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Linq;

namespace SolutionOne_DataAccessLayer.Repositories.RBAC.Implementation
{
    public class PermissionRepository : IPermissionRepository
    {
        private readonly IDapperContext _context;

        public PermissionRepository(IDapperContext context)
        {
            _context = context;
        }

        public async Task<IEnumerable<string>> GetRolesByUserIdAsync(int userId)
        {
            var query = @"
                SELECT r.RoleName 
                FROM HR_RolesMaster r
                INNER JOIN HR_UserRoles ur ON r.RoleId = ur.RoleId
                WHERE ur.UserId = @UserId";

            return await _context.Connection.QueryAsync<string>(query, new { UserId = userId });
        }

        // The single read of "which roles does this user hold": HR_UserRoles -> HR_RolesMaster.
        // ICurrentUserAccess and PermissionResolver both go through here - nothing else decides roles.
        public async Task<IEnumerable<RoleAccessDto>> GetRoleAccessByUserIdAsync(int userId)
        {
            var query = @"
                -- Same row set GetRolesByUserIdAsync returns (no IsActive filter, so existing
                -- permission behaviour is unchanged); only the super-admin grant itself requires
                -- the role to be active, so a deactivated Admin role can't keep granting everything.
                SELECT r.RoleName,
                       CAST(CASE WHEN ISNULL(r.IsActive, 1) = 1 THEN ISNULL(r.IsSuperAdmin, 0) ELSE 0 END AS BIT) AS IsSuperAdmin
                FROM HR_RolesMaster r
                INNER JOIN HR_UserRoles ur ON r.RoleId = ur.RoleId
                WHERE ur.UserId = @UserId";

            return await _context.Connection.QueryAsync<RoleAccessDto>(query, new { UserId = userId });
        }

        // Every (menu, action) pair - what a super-admin role is granted instead of reading
        // HR_RolePermissions row by row (a menu added tomorrow needs no re-seeding).
        public async Task<IEnumerable<RolePermissionDto>> GetAllPermissionPairsAsync()
        {
            var query = @"
                SELECT 0 AS RoleId, mi.MenuID, mi.MainMenu AS MenuCode, mi.NavigateUrl, ma.ActionId, ma.ActionCode
                FROM HR_MenuItems mi
                CROSS JOIN HR_MenuActions ma";

            return await _context.Connection.QueryAsync<RolePermissionDto>(query);
        }

        public async Task<IEnumerable<RolePermissionDto>> GetPermissionsByRolesAsync(IEnumerable<string> roles)
        {
            if (roles == null || !roles.Any()) return new List<RolePermissionDto>();

            var query = @"
                SELECT rp.RoleId, rp.MenuID, mi.MainMenu as MenuCode, mi.NavigateUrl, rp.ActionId, ma.ActionCode as ActionCode
                FROM HR_RolePermissions rp
                INNER JOIN HR_RolesMaster r ON rp.RoleId = r.RoleId
                INNER JOIN HR_MenuItems mi ON mi.MenuID = rp.MenuId
                INNER JOIN HR_MenuActions ma on ma.ActionId = rp.ActionId
                WHERE r.RoleName IN @Roles";

            return await _context.Connection.QueryAsync<RolePermissionDto>(query, new { Roles = roles });
        }

        public async Task<IEnumerable<RolePermissionDto>> GetUserScreenAccessAsync(int userId)
        {
            // Deliberately not filtered on HR_MenuItems.IsActive (same as the role path): a menu sync can
            // retire and re-insert a row, and the grant is matched by MainMenu / NavigateUrl text, so it
            // keeps working. The ".aspx" filter is the one hard rule - a payroll page never becomes one of
            // our permissions. OBJECT_ID guard: a database the migration has not reached yet resolves to
            // "no direct access" instead of failing every login.
            var query = @"
                IF OBJECT_ID(N'dbo.HR_UserScreenAccess', N'U') IS NULL
                    SELECT 0 AS RoleId, CAST(0 AS BIGINT) AS MenuID, '' AS MenuCode, '' AS NavigateUrl,
                           0 AS ActionId, '' AS ActionCode
                    WHERE 1 = 0
                ELSE
                    SELECT 0 AS RoleId, sa.MenuId AS MenuID, mi.MainMenu AS MenuCode, mi.NavigateUrl,
                           sa.ActionId, ma.ActionCode
                    FROM HR_UserScreenAccess sa
                    INNER JOIN HR_MenuItems mi ON mi.MenuID = sa.MenuId
                    INNER JOIN HR_MenuActions ma ON ma.ActionId = sa.ActionId
                    WHERE sa.UserId = @UserId
                      AND ISNULL(ma.IsActive, 1) = 1
                      AND mi.NavigateUrl IS NOT NULL AND mi.NavigateUrl NOT LIKE '%.aspx%'";

            return await _context.Connection.QueryAsync<RolePermissionDto>(query, new { UserId = userId });
        }

        public async Task<IEnumerable<UserPermissionOverrideDto>> GetUserPermissionOverridesAsync(int userId)
        {
            // This used to select only UserId/MenuID/ActionID, so MenuCode/ActionCode/IsRevoked were never
            // populated and every override resolved to a junk ":" entry - overrides had no effect at all.
            // Now returns the codes (and route) the resolver needs, only rows that grant or revoke, and
            // only inside their effective window.
            var query = @"
                SELECT up.UserId, up.MenuId AS MenuID, up.ActionId,
                       CAST(ISNULL(up.IsRevoked, 0) AS BIT) AS IsRevoked,
                       mi.MainMenu AS MenuCode, mi.NavigateUrl, ma.ActionCode
                FROM HR_UserPermissions up
                INNER JOIN HR_MenuItems mi ON mi.MenuID = up.MenuId
                INNER JOIN HR_MenuActions ma ON ma.ActionId = up.ActionId
                WHERE up.UserId = @UserId
                  AND (ISNULL(up.IsGranted, 1) = 1 OR ISNULL(up.IsRevoked, 0) = 1)
                  AND (up.EffectiveFrom IS NULL OR up.EffectiveFrom <= SYSUTCDATETIME())
                  AND (up.EffectiveTo IS NULL OR up.EffectiveTo >= SYSUTCDATETIME())";

            return await _context.Connection.QueryAsync<UserPermissionOverrideDto>(query, new { UserId = userId });
        }

        public async Task<int> GetPermissionVersionAsync(int userId)
        {
            var query = @"
                SELECT ISNULL(PermissionVersion, 1)
                FROM HR_UserMaster
                WHERE UserMasterId = @UserId";

            return await _context.Connection.QueryFirstOrDefaultAsync<int>(query, new { UserId = userId });
        }
    }
}

