using Dapper;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;
using SolutionOne_Core.CommonModels.RBAC;
using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
using SolutionOne_DataAccessLayer.Repositories.RBAC.Interface;

namespace SolutionOne_DataAccessLayer.Repositories.RBAC.Implementation
{
	public class UserScreenAccessRepository(
		IDapperContext context,
		IMemoryCache cache,
		ILogger<UserScreenAccessRepository> logger) : IUserScreenAccessRepository
	{
		public async Task<bool> UserExistsAsync(int userId)
		{
			var found = await context.Connection.ExecuteScalarAsync<int?>(
				"SELECT 1 FROM HR_UserMaster WHERE UserMasterID = @UserId",
				new { UserId = userId });
			return found.HasValue;
		}

		public async Task<IReadOnlyList<UserScreenAccessItemDto>> GetByUserAsync(int userId)
		{
			var rows = await context.Connection.QueryAsync<UserScreenAccessItemDto>(
				@"SELECT MenuId, ActionId
				  FROM HR_UserScreenAccess
				  WHERE UserId = @UserId",
				new { UserId = userId });
			return rows.ToList();
		}

		public async Task<IReadOnlyList<RolePermissionDto>> GetAssignablePairsAsync(IReadOnlyCollection<UserScreenAccessItemDto> requested)
		{
			if (requested.Count == 0)
				return new List<RolePermissionDto>();

			// Same catalog scope as MenuHandleRepository.NonPayrollMenuFilterSql: hr_payroll's rows are the
			// ones whose NavigateUrl is an .aspx page; they can never be assigned from here.
			var rows = await context.Connection.QueryAsync<RolePermissionDto>(
				@"SELECT 0 AS RoleId, mi.MenuID, mi.MainMenu AS MenuCode, mi.NavigateUrl,
				         ma.ActionId, ma.ActionCode
				  FROM HR_MenuItems mi
				  CROSS JOIN HR_MenuActions ma
				  WHERE mi.MenuID IN @MenuIds
				    AND ma.ActionId IN @ActionIds
				    AND ISNULL(mi.IsActive, 1) = 1
				    AND ISNULL(ma.IsActive, 1) = 1
				    AND mi.NavigateUrl IS NOT NULL AND mi.NavigateUrl <> '' AND mi.NavigateUrl NOT LIKE '%.aspx%'",
				new
				{
					MenuIds = requested.Select(r => r.MenuId).Distinct().ToArray(),
					ActionIds = requested.Select(r => r.ActionId).Distinct().ToArray()
				});
			return rows.ToList();
		}

		public async Task ApplyChangesAsync(
			int userId,
			IReadOnlyCollection<UserScreenAccessItemDto> toAdd,
			IReadOnlyCollection<UserScreenAccessItemDto> toRemove,
			long? assignedBy)
		{
			if (toAdd.Count == 0 && toRemove.Count == 0)
				return;

			logger.LogInformation(
				"Applying direct screen access for User ID {UserId}: {Added} to add, {Removed} to remove.",
				userId, toAdd.Count, toRemove.Count);

			await context.BeginTransactionAsync();
			try
			{
				if (toRemove.Count > 0)
				{
					await context.Connection.ExecuteAsync(
						@"DELETE FROM HR_UserScreenAccess
						  WHERE UserId = @UserId AND MenuId = @MenuId AND ActionId = @ActionId",
						toRemove.Select(r => new { UserId = userId, r.MenuId, r.ActionId }).ToList(),
						context.Transaction);
				}

				if (toAdd.Count > 0)
				{
					// NOT EXISTS keeps a repeated save (or two admins saving at once) from tripping the primary key.
					await context.Connection.ExecuteAsync(
						@"INSERT INTO HR_UserScreenAccess (UserId, MenuId, ActionId, AssignedBy, AssignedDate)
						  SELECT @UserId, @MenuId, @ActionId, @AssignedBy, SYSUTCDATETIME()
						  WHERE NOT EXISTS (SELECT 1 FROM HR_UserScreenAccess
						                    WHERE UserId = @UserId AND MenuId = @MenuId AND ActionId = @ActionId)",
						toAdd.Select(a => new { UserId = userId, a.MenuId, a.ActionId, AssignedBy = assignedBy }).ToList(),
						context.Transaction);
				}

				await context.Connection.ExecuteAsync(
					@"UPDATE HR_UserMaster
					  SET PermissionVersion = ISNULL(PermissionVersion, 1) + 1
					  WHERE UserMasterID = @UserId",
					new { UserId = userId },
					context.Transaction);

				await context.CommitAsync();
			}
			catch (Exception ex)
			{
				logger.LogError(ex, "Database error applying direct screen access for User ID {UserId}. Rolling back.", userId);
				await context.RollbackAsync();
				throw;
			}

			// Same keys PermissionFilter / PermissionChecker read, so the new rights apply on the next request.
			cache.Remove(PermissionCacheKeys.Version(userId));
			cache.Remove(PermissionCacheKeys.Permissions(userId));
		}
	}
}
