import { isRouteImplemented, normalizeRoute } from './implemented-routes';

/**
 * Builds the left navigation from the two things the database defines it with:
 *
 *   HR_MenuGroups / vw_HR_MenuGroupTree  -> the folder tree (order, nesting, icons)
 *   HR_MenuItems  x  HR_UserMenuRights   -> the screens this user is granted
 *
 * This is a port of Payroll.master.cs (BuildNestedMenu / AddBranch / LoadFolderTree) from the
 * sibling hr_payroll WebForms project. Both apps read the same tables in the same database, so
 * reproducing its grouping rules here is what makes the two navigations identical - move a
 * screen in Menu Configuration and it moves in both.
 *
 * The rules that are easy to get wrong, all of them load-bearing:
 *
 *  - A screen is matched to its folder by NAME (HR_MenuItems.ParentMenu = GroupName), not by id.
 *  - IsActive = 0 on a folder hides that folder AND its whole branch - sub-folders and every
 *    screen filed under any of them. Un-ticking Active in Menu Configuration is the documented
 *    way to hide a branch.
 *  - A screen whose ParentMenu matches NO folder is a data gap, not a decision, so it still
 *    gets shown - in a flat group of its own, after the real tree.
 *  - Those two cases must not be confused. Hidden folder names have to be carried out of the
 *    tree walk, otherwise the "data gap" rescue above hands a de-activated group straight back
 *    as a flat group with the same caption - which is the bug this ordering exists to avoid.
 *  - Within a folder: sub-folders first, then that folder's own screens.
 *  - An empty group is dropped. It is legitimately empty whenever the user has rights to none
 *    of the screens inside it.
 */

/** Folder tree row, as returned by GET /api/MenuHandle/FetchMenuGroups. */
export interface MenuGroupRecord {
  groupId: number;
  parentGroupId: number | null;
  groupName: string;
  groupIcon: string;
  nodeLevel: number;
  isActive: boolean;
  sortPath: string;
  displayOrder: number;
}

/** A rendered row. Matches what sidenav.component.html / tree-view expect. */
export interface NavNode {
  label: string;
  routeLink?: string;
  url?: string;
  target?: string;
  icon: string;
  expanded: boolean;
  items: NavNode[];
}

/** One HR_MenuItems row, after the casing of the API is normalised away. */
export interface MenuRecord {
  mainMenu: string;
  mainMenuText: string;
  parentMenu: string;
  menuIcon: string;
  parentMenuIcon: string;
  navigateUrl: string;
  displayOrder: number;
}

/**
 * Folders may nest 4 deep, so a screen sits at 5. vw_HR_MenuGroupTree already caps this;
 * enforced again here because the cap is also what keeps a cyclic ParentGroupID from recursing
 * forever, and a view is easier to change than this file.
 */
const MAX_MENU_DEPTH = 5;

const DEFAULT_FOLDER_ICON = 'fa-solid fa-folder';

interface FolderNode {
  groupId: number;
  groupName: string;
  groupIcon: string;
  children: FolderNode[];
}

/** Folder names are the join key, so compare them the way SQL Server would. */

