/** Folder names are the join key, so compare them the way SQL Server would. */
function key(name: string | null | undefined): string {
  return String(name ?? '')
    .trim()
    .toLowerCase();
}

/**
 * HR_MenuGroups.GroupIcon is written by the WebForms Menu Configuration screen, which stores a
 * DevExpress IconID ("businessobjects_bo_organization_svg_16x16") - it resolves to a sprite in
 * that app and to nothing at all here. HR_MenuItems.MenuIcon / ParentMenuIcon, written by this
 * app, hold real CSS classes ("fa-solid fa-users").
 *
 * One column, two icon vocabularies, and no flag distinguishing them - so tell them apart by
 * shape. Anything that does not look like a CSS class is dropped rather than rendered, because
 * putting an IconID into class="" produces a stray un-styled element, not a missing one.
 */
function asCssIcon(icon: string | null | undefined): string {
  const value = String(icon ?? '').trim();
  if (!value) return '';

  // A DevExpress IconID is a single lower_snake_case token; a class list has a space, and a
  // lone icon class still carries its library prefix.
  if (/\s/.test(value)) return value;
  if (/^(fa[srlbd]?-|fa$|bi-|icon-|dx-icon-|pi-|material-icons)/i.test(value)) return value;

  return '';
}

export function normalizeMenuRecord(menu: Record<string, unknown>): MenuRecord {
  const pick = (...names: string[]): string => {
    for (const n of names) {
      const v = menu[n];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  return {
    mainMenu: pick('mainMenu', 'MainMenu'),
    mainMenuText: pick('mainMenuText', 'MainMenuText'),
    parentMenu: pick('parentMenu', 'ParentMenu'),
    menuIcon: pick('menuIcon', 'MenuIcon'),
    parentMenuIcon: pick('parentMenuIcon', 'ParentMenuIcon'),
    navigateUrl: pick('navigateUrl', 'NavigateUrl'),
    displayOrder: Number(menu['displayOrder'] ?? menu['DisplayOrder'] ?? 0) || 0,
  };
}

export function normalizeGroupRecord(group: Record<string, unknown>): MenuGroupRecord {
  const num = (...names: string[]): number => {
    for (const n of names) {
      const v = group[n];
      if (v !== undefined && v !== null && v !== '') return Number(v) || 0;
    }
    return 0;
  };
  const str = (...names: string[]): string => {
    for (const n of names) {
      const v = group[n];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  const rawParent = group['parentGroupId'] ?? group['ParentGroupID'] ?? group['ParentGroupId'];
  const rawActive = group['isActive'] ?? group['IsActive'];

  let ret = {
    groupId: num('groupId', 'GroupID', 'GroupId'),
    parentGroupId:
      rawParent === undefined || rawParent === null || rawParent === '' ? null : Number(rawParent),
    groupName: str('groupName', 'GroupName'),
    groupIcon: str('groupIcon', 'GroupIcon'),
    nodeLevel: num('nodeLevel', 'NodeLevel') || 1,
    // A NULL IsActive means active, matching ISNULL(IsActive, 1) on the SQL side.
    isActive: rawActive === undefined || rawActive === null ? true : Boolean(rawActive),
    sortPath: str('sortPath', 'SortPath'),
    displayOrder: num('displayOrder', 'DisplayOrder'),
  };
  return ret;
}

/** A screen row -> a rendered leaf. Returns null when the row is not navigable. */
function toScreenNode(menu: MenuRecord): NavNode | null {
  const label = menu.mainMenuText || menu.mainMenu;
  if (!label) return null;

  const raw = menu.navigateUrl;
  if (!raw) return null;

  // An absolute URL is an external hop (the payroll nav uses one for the recruitment portal
  // SSO). It is not an app route, so the implemented-route check does not apply to it.
  if (/^https?:\/\//i.test(raw)) {
    return {
      label,
      url: raw,
      target: '_blank',
      icon: asCssIcon(menu.menuIcon),
      expanded: false,
      items: [],
    };
  }

  // Hide anything this build cannot actually open - see implemented-routes.ts. Notably this
  // drops the hr_payroll project's own ".aspx" rows, which share the table but are not routes
  // in this app.
  if (!isRouteImplemented(raw)) return null;

  return {
    label,
    routeLink: normalizeRoute(raw),
    icon: asCssIcon(menu.menuIcon),
    expanded: false,
    items: [],
  };
}

/**
 * Sub-folders first, then this folder's own screens - so every level reads
 * "groups first, then modules", exactly as AddBranch emits them.
 */
function buildBranch(
  folder: FolderNode,
  screensByFolder: Map<string, NavNode[]>,
  placed: Set<string>,
  folderLevel: number,
): NavNode[] {
  const rows: NavNode[] = [];

  if (folderLevel < MAX_MENU_DEPTH) {
    for (const child of folder.children) {
      const childLevel = folderLevel + 1;

      // A folder has to stop at level 4 so its screens still fit inside the 5-level ceiling.
      if (childLevel >= MAX_MENU_DEPTH) continue;

      const childRows = buildBranch(child, screensByFolder, placed, childLevel);

      // Drop a sub-folder that ended up with nothing the user may open.
      if (childRows.length === 0) continue;

      rows.push({
        label: child.groupName,
        icon: child.groupIcon || DEFAULT_FOLDER_ICON,
        expanded: false,
        items: childRows,
      });
    }
  }

  const own = screensByFolder.get(key(folder.groupName));
  if (own) {
    placed.add(key(folder.groupName));
    rows.push(...own);
  }

  return rows;
}

/**
 * @param menus  HR_MenuItems rows the user is entitled to (already rights-filtered server-side)
 * @param groups vw_HR_MenuGroupTree rows in SortPath order; empty when the database has no
 *               folder tree, in which case grouping falls back to ParentMenu alone.
 */
export function buildNavTree(
  menus: Record<string, unknown>[],
  groups: Record<string, unknown>[],
): NavNode[] {
  const records = (menus ?? []).map(normalizeMenuRecord);

  // ORDER BY ISNULL(DisplayOrder, 999), MainMenuText, MainMenu - the screen order the
  // WebForms nav uses. Sort before bucketing so each folder's contents come out ordered.
  const ordered = [...records].sort(
    (a, b) =>
      (a.displayOrder || 999) - (b.displayOrder || 999) ||
      a.mainMenuText.localeCompare(b.mainMenuText) ||
      a.mainMenu.localeCompare(b.mainMenu),
  );

  // Screens with no ParentMenu are top-level links in their own right (e.g. Home).
  const rootItems: NavNode[] = [];
  const screensByFolder = new Map<string, NavNode[]>();
  // The folder's caption as the data spells it, for the "no such folder" rescue below.
  const folderCaption = new Map<string, string>();
  const folderIconFromScreens = new Map<string, string>();

  for (const menu of ordered) {
    const node = toScreenNode(menu);
    if (!node) continue;

    if (!menu.parentMenu) {
      rootItems.push(node);
      continue;
    }

    const k = key(menu.parentMenu);
    if (!screensByFolder.has(k)) {
      screensByFolder.set(k, []);
      folderCaption.set(k, menu.parentMenu);
    }
    screensByFolder.get(k)!.push(node);

    const parentIcon = asCssIcon(menu.parentMenuIcon);
    if (parentIcon && !folderIconFromScreens.has(k)) {
      folderIconFromScreens.set(k, parentIcon);
    }
  }

  const groupRows = (groups ?? []).map(normalizeGroupRecord).filter((g) => g.groupName);

  // ---- Rebuild the folder tree ---------------------------------------------------------
  // SortPath order guarantees a parent is seen before its children, so one pass is enough.
  // A de-activated folder is deliberately NOT registered in byId: its own children then miss
  // the same lookup and the whole branch drops out together.
  const byId = new Map<number, FolderNode>();
  const roots: FolderNode[] = [];
  const hiddenGroups = new Set<string>();

  for (const g of groupRows) {
    let parent: FolderNode | undefined;
    let insideHiddenBranch = false;

    if (g.parentGroupId !== null) {
      parent = byId.get(g.parentGroupId);
      // Every in-range parent has already been read, so a miss means the parent was dropped
      // as hidden - i.e. this folder sits inside a hidden branch.
      insideHiddenBranch = !parent;
    }

    if (!g.isActive || insideHiddenBranch) {
      hiddenGroups.add(key(g.groupName));
      continue;
    }

    const folder: FolderNode = {
      groupId: g.groupId,
      groupName: g.groupName,
      // The screens' own ParentMenuIcon wins: it is always a CSS class, whereas GroupIcon is
      // usually a DevExpress IconID this app cannot render.
      groupIcon: folderIconFromScreens.get(key(g.groupName)) || asCssIcon(g.groupIcon),
      children: [],
    };

    byId.set(g.groupId, folder);
    if (parent) parent.children.push(folder);
    else roots.push(folder);
  }

  // ---- Emit ----------------------------------------------------------------------------
  const placed = new Set<string>();
  const groupNodes: NavNode[] = [];

  for (const root of roots) {
    const rows = buildBranch(root, screensByFolder, placed, 1);
    if (rows.length === 0) continue;

    groupNodes.push({
      label: root.groupName,
      icon: root.groupIcon || DEFAULT_FOLDER_ICON,
      expanded: false,
      items: rows,
    });
  }

  // Screens whose folder has no HR_MenuGroups row at all must not disappear - that is a data
  // gap, not a decision. A folder the admin un-ticked Active on is different: it is hidden on
  // purpose, so the screens filed under it stay hidden with it.
  for (const [k, items] of screensByFolder) {
    if (placed.has(k) || hiddenGroups.has(k) || items.length === 0) continue;

    groupNodes.push({
      label: folderCaption.get(k) ?? k,
      icon: folderIconFromScreens.get(k) || DEFAULT_FOLDER_ICON,
      expanded: false,
      items,
    });
  }

  return [...rootItems, ...groupNodes];
}

