/** Folder names are the join key, so compare them the way SQL Server would. */
function key(name: string | null | undefined): string {
  return String(name ?? '')
    .trim()
    .toLowerCase();
}

/**
 * HR_MenuGroups.GroupIcon is written by the WebForms Menu Configuration screen, which stores a
 * DevExpress IconID ("businessobjects_bo_organization_svg_16x16") - it resolves to a sprite in
 * that app and to nothing at all here. HR_MenuItems.MenuIcon / ParentMenuIcon, written by this
 * app, hold real CSS classes ("fa-solid fa-users").
 *
 * One column, two icon vocabularies, and no flag distinguishing them - so tell them apart by
 * shape. Anything that does not look like a CSS class is dropped rather than rendered, because
 * putting an IconID into class="" produces a stray un-styled element, not a missing one.
 */
function asCssIcon(icon: string | null | undefined): string {
  const value = String(icon ?? '').trim();
  if (!value) return '';

  // A DevExpress IconID is a single lower_snake_case token; a class list has a space, and a
  // lone icon class still carries its library prefix.
  if (/\s/.test(value)) return value;
  if (/^(fa[srlbd]?-|fa$|bi-|icon-|dx-icon-|pi-|material-icons)/i.test(value)) return value;

  return '';
}

export function normalizeMenuRecord(menu: Record<string, unknown>): MenuRecord {
  const pick = (...names: string[]): string => {
    for (const n of names) {
      const v = menu[n];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  return {
    mainMenu: pick('mainMenu', 'MainMenu'),
    mainMenuText: pick('mainMenuText', 'MainMenuText'),
    parentMenu: pick('parentMenu', 'ParentMenu'),
    menuIcon: pick('menuIcon', 'MenuIcon'),
    parentMenuIcon: pick('parentMenuIcon', 'ParentMenuIcon'),
    navigateUrl: pick('navigateUrl', 'NavigateUrl'),
    displayOrder: Number(menu['displayOrder'] ?? menu['DisplayOrder'] ?? 0) || 0,
  };
}

export function normalizeGroupRecord(group: Record<string, unknown>): MenuGroupRecord {
  const num = (...names: string[]): number => {
    for (const n of names) {
      const v = group[n];
      if (v !== undefined && v !== null && v !== '') return Number(v) || 0;
    }
    return 0;
  };
  const str = (...names: string[]): string => {
    for (const n of names) {
      const v = group[n];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  const rawParent = group['parentGroupId'] ?? group['ParentGroupID'] ?? group['ParentGroupId'];
  const rawActive = group['isActive'] ?? group['IsActive'];

  let ret = {
    groupId: num('groupId', 'GroupID', 'GroupId'),
    parentGroupId:
      rawParent === undefined || rawParent === null || rawParent === '' ? null : Number(rawParent),
    groupName: str('groupName', 'GroupName'),
    groupIcon: str('groupIcon', 'GroupIcon'),
    nodeLevel: num('nodeLevel', 'NodeLevel') || 1,
    // A NULL IsActive means active, matching ISNULL(IsActive, 1) on the SQL side.
    isActive: rawActive === undefined || rawActive === null ? true : Boolean(rawActive),
