import { Injectable, computed, signal } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject, firstValueFrom } from 'rxjs';
import { ApiService } from './api.service';
import { buildPermissionIndex, normalizePermissionKey } from './permission-index';
import { decryptData, encryptData } from './utils';

@Injectable({ providedIn: 'root' })
export class AuthService {
  isAuthenticated = false;
  _EditRequitionId: string | null = null;
  _EditManageRating: string | null = null;
  _EditTripRequestId: string | null = null;

  private screenNameSubject = new BehaviorSubject<string>('Dashboard');
  screenName$ = this.screenNameSubject.asObservable();

  private menusUpdatedSubject = new BehaviorSubject<void>(undefined);
  menusUpdated$ = this.menusUpdatedSubject.asObservable();

  private readonly publicRoutes = new Set([
    '/dashboard',
    '/my-dashboard',
    '/org-chart',
    '/home',
    '/vms/visitor-entry',
    '/vms/approve-visitor',
    '/vms/visitor-list',
    '/vms/',
    '/vms/visitor-entry/:id',
    '/vms/gate-pass-template',
    '/vms/gate-pass-template/:id',
    '/vms/guest-upload',
    '/vms/guest-view',
    '/admin/hr-config'
  ]);

  notifyMenusUpdated(): void {
    this.menusUpdatedSubject.next();
  }

  set ScreenName(name: string) {
    const next = name ?? '';
    if (next === this.screenNameSubject.getValue()) {
      return;
    }
    queueMicrotask(() => this.screenNameSubject.next(next));
  }

  get ScreenName(): string {
    return this.screenNameSubject.getValue();
  }

  /**
   * The user's resolved permissions ("<menu>:<ACTION>") as stored at login, held in a signal so
   * screens and the appHasPermission directive react if they change (new login, logout). This is a
   * convenience for hiding buttons - the backend is what actually enforces a right.
   */
  private readonly permissionsSignal = signal<string[]>([]);
  readonly permissionIndex = computed(() => buildPermissionIndex(this.permissionsSignal()));

  constructor(
    private router: Router,
    private apiService: ApiService,
  ) {
    this.refreshPermissions();
  }

  /** Re-reads the stored permissions into the signal. Call after anything that writes them. */
  private refreshPermissions(): void {
    this.permissionsSignal.set(this.getPermissions());
  }

  /** Does the user hold <action> on this screen? <menu> is a route or a MainMenu code. */
  can(menu: string, action: string): boolean {
    return this.permissionIndex().get(normalizePermissionKey(menu))?.has(action.toUpperCase()) ?? false;
  }

  normalizeAppRoute(url: string): string {
    const raw = (url ?? '').split('?')[0].trim();
    if (!raw) {
      return '/';
    }

    const withSlash = raw.startsWith('/') ? raw : `/${raw}`;
    const normalized = withSlash.replace(/\/+$/, '');
    return normalized || '/';
  }

  getToken(): string {
    return (localStorage.getItem('token') ?? '').trim();
  }

  getCompanyId(): number {
    return Number(localStorage.getItem('companyId') ?? 0);
  }

  getBranchId(): number {
    return Number(localStorage.getItem('branchId') ?? 0);
  }

  getEmployeeId(): number {
    return Number(localStorage.getItem('employeeId') ?? 0);
  }

  /**
   * Is the signed-in login user linked to an employee? An account with no employee (the top "edp" admin,
   * operator accounts) logs in and has rights like anyone else, but acts on no employee record: the token
   * carries an employee id of 0. Screens and features that are "about me as an employee" don't apply to it.
   */
  hasEmployee(): boolean {
    return this.getEmployeeId() > 0;
  }

  isLoggedIn(): boolean {
    return !!this.getToken();
  }

  getPermissions(): string[] {
    const raw = localStorage.getItem('permissions') ?? localStorage.getItem('rights');
    if (!raw) {
      return [];
    }
    const data = decryptData(raw);
    return Array.isArray(data) ? data.map((p) => String(p)) : [];
  }

  getMenus(): Record<string, unknown>[] {
    const raw = localStorage.getItem('menus');
    if (!raw) {
      return [];
    }
    const data = decryptData(raw);
    return Array.isArray(data) ? data : [];
  }

  /**
   * The folder tree the sidebar groups its screens into (HR_MenuGroups / vw_HR_MenuGroupTree),
   * cached from the last loadMenuGroups() call.
   *
   * Cached rather than fetched on every render because it is small, changes only when an admin
   * edits Menu Configuration, and the sidebar has to paint before any request could come back.
   * An empty list is a valid answer - the sidebar then groups by ParentMenu alone, which is
   * what it did before the tree existed.
   */
  getMenuGroups(): Record<string, unknown>[] {
    const raw = localStorage.getItem('menuGroups');
    if (!raw) {
      return [];
    }
    const data = decryptData(raw);
    return Array.isArray(data) ? data : [];
  }

  /**
   * Refreshes the cached folder tree. Safe to call on every sidebar build: a failure leaves the
   * previous cache in place and resolves false, so a menu-groups outage degrades the grouping
   * instead of emptying the navigation.
   */
  async loadMenuGroups(): Promise<boolean> {
    if (!this.isLoggedIn()) {
      return false;
    }

    try {
      const res = await firstValueFrom(this.apiService.get('/api/MenuHandle/FetchMenuGroups'));
      const groups = res?.data ?? res?.Data ?? [];

      if (!Array.isArray(groups)) {
        return false;
      }

      localStorage.setItem('menuGroups', encryptData(groups));
      return true;
    } catch {
      // Keep whatever is cached - see the doc comment above.
      return false;
    }
  }

  hasPermission(menuCode: string, action: string): boolean {
    const key = `${menuCode}:${action}`.toLowerCase();
    return this.getPermissions().some((p) => p.toLowerCase() === key);
  }

  canShowMenu(mainMenu: string): boolean {
    const code = (mainMenu ?? '').trim();
    if (!code) {
      return false;
    }

    return this.getMenus().some(
      (m) => String(m['mainMenu'] ?? m['MainMenu'] ?? '').toLowerCase() === code.toLowerCase(),
    );
  }

  hasRouteAccess(url: string): boolean {
    const path = this.normalizeAppRoute(url);
    if (this.publicRoutes.has(path)) {
      return true;
    }

    // Allow sub-routes/parameterized URLs of public routes (e.g. /vms/visitor-entry/12)
    for (const publicRoute of this.publicRoutes) {
      if (path.startsWith(`${publicRoute}/`)) {
        return true;
      }
    }

    const menus = this.getMenus();
    if (!menus.length) {
      return false;
    }

    return menus.some((menu) => {
      const navigateUrl = String(menu['navigateUrl'] ?? menu['NavigateUrl'] ?? '').trim();
      if (!navigateUrl || navigateUrl.startsWith('http')) {
        return false;
      }

      const menuPath = this.normalizeAppRoute(navigateUrl);
      return path === menuPath || path.startsWith(`${menuPath}/`);
    });
  }

  saveGuestSession(jwtToken: string): void {
    localStorage.setItem('token', jwtToken.trim());
    localStorage.setItem('role', 'Guest');
    localStorage.removeItem('menus');
    localStorage.removeItem('menuGroups');
    localStorage.removeItem('permissions');
    localStorage.removeItem('rights');
    this.isAuthenticated = true;
  }

  isGuestSession(): boolean {
    const token = this.getToken();
    if (!token) return false;
    try {
      const payloadBase64 = token.split('.')[1];
      if (!payloadBase64) return false;
      const payload = JSON.parse(atob(payloadBase64.replace(/-/g, '+').replace(/_/g, '/')));
      const role = payload.role ?? payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'];
      if (Array.isArray(role)) return role.includes('Guest');
      return role === 'Guest';
    } catch {
      return localStorage.getItem('role') === 'Guest';
    }
  }

  saveSession(loginPayload: Record<string, unknown>): boolean {
    const token = String(loginPayload['token'] ?? loginPayload['Token'] ?? '').trim();
    if (!token) {
      return false;
    }

    localStorage.setItem('token', token);
    this.isAuthenticated = true;

    localStorage.setItem('userId', String(loginPayload['userId'] ?? loginPayload['UserId'] ?? 0));
    localStorage.setItem(
      'userName',
      String(loginPayload['userName'] ?? loginPayload['UserName'] ?? ''),
    );
    localStorage.setItem(
      'companyId',
      String(loginPayload['companyId'] ?? loginPayload['CompanyId'] ?? 0),
    );
    localStorage.setItem(
      'branchId',
      String(loginPayload['branchId'] ?? loginPayload['BranchId'] ?? 0),
    );
    localStorage.setItem(
      'employeeId',
      String(loginPayload['employeeId'] ?? loginPayload['EmployeeId'] ?? 0),
    );

    const roles = loginPayload['roles'] ?? loginPayload['Roles'];
    if (Array.isArray(roles) && roles.length > 0) {
      localStorage.setItem('role', String(roles[0]));
      localStorage.setItem('roles', encryptData(roles));
    } else {
      localStorage.setItem('role', String(loginPayload['role'] ?? loginPayload['Role'] ?? 'User'));
    }

