public async Task<(ResponseModel, List<ListAllMenu>?)> GetUserMenusAsync(int userId)
{
    var response = new ResponseModel();
    if (userId <= 0)
    {
        response.IsSuccess = false;
        response.Status = HttpStatusCode.BadRequest;
        response.Message = "Valid user id is required.";
        return (response, null);
    }

    try
    {
        var permissions = await _permissionResolver.ResolvePermissionsAsync(userId);
        var merged = await ResolveUserMenusAsync(permissions);

        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        response.Message = "Menus loaded.";
        return (response, merged);
    }
    catch (Exception ex)
    {
        response.IsSuccess = false;
        response.Status = HttpStatusCode.InternalServerError;
        response.Message = ex.Message;
        return (response, new List<ListAllMenu>());
    }
}

public async Task<ListUserModel?> GetUserByUsername(string username)
{
    var user = await _loginRepository.GetUserByUsername(username);

    if (user == null)
        return null;

    return new ListUserModel
    {
        UserMasterId = user.UserMasterId,
        UserName = user.UserName
    };
}

/// <summary>
/// The screens a user can open: every active screen of THIS app they hold at least one permission on
/// (from a role, directly assigned screen access, or an override). Never reads hr_payroll's
/// HR_UserMenuRights - the two systems' menu access is separate by design.
/// </summary>
private async Task<List<ListAllMenu>> ResolveUserMenusAsync(HashSet<string>? permissions)
{
    var allMenus = await _menuHandleRepository.FetchAllMenu(null);
    var permissionMenus = permissions == null
        ? new List<ListAllMenu>()
        : allMenus
            .Where(m =>
                m.IsActive == true &&
                !string.IsNullOrEmpty(m.MainMenu) &&
                permissions.Any(p => p.StartsWith($"{m.MainMenu}:", StringComparison.OrdinalIgnoreCase)))
            .ToList();

    return permissionMenus
        .GroupBy(m => (m.NavigateUrl ?? string.Empty).Trim().ToLowerInvariant())
        .Where(g => !string.IsNullOrWhiteSpace(g.Key))
        .Select(g => g.First())
        .OrderBy(m => m.DisplayOrder ?? 0)
        .ThenBy(m => m.MenuId ?? 0)
        .ToList();
}

/// <summary>
/// HR_UserMaster.PasswordHash is reversible AES encryption (PasswordEncryptionHelper),
/// matching the sibling hr_payroll project - not a deterministic hash. A fresh
/// encryption of the submitted password can never be compared to the stored value
/// directly (random IV each time), so this decrypts the stored value and compares
/// plaintext-to-plaintext instead, exactly like hr_payroll's AuthHelper.ValidateCredentials.
/// A stored value that fails to decrypt (e.g. a leftover value from this project's old
/// SHA256 scheme) is treated as a non-match, not an error.
/// </summary>
