public async Task<(ResponseModel, List<ListAllMenu>?)> GetUserMenusAsync(int userId)
{
    var response = new ResponseModel();
    if (userId <= 0)
    {
        response.IsSuccess = false;
        response.Status = HttpStatusCode.BadRequest;
        response.Message = "Valid user id is required.";
        return (response, null);
    }

    try
    {
        var permissions = await _permissionResolver.ResolvePermissionsAsync(userId);
        var merged = await ResolveUserMenusAsync(permissions);

        response.IsSuccess = true;
        response.Status = HttpStatusCode.OK;
        response.Message = "Menus loaded.";
        return (response, merged);
    }
    catch (Exception ex)
    {
        response.IsSuccess = false;
        response.Status = HttpStatusCode.InternalServerError;
        response.Message = ex.Message;
        return (response, new List<ListAllMenu>());
    }
}

public async Task<ListUserModel?> GetUserByUsername(string username)
{
