    if (user == null)
        return null;

    return new ListUserModel
    {
        UserMasterId = user.UserMasterId,
        UserName = user.UserName
    };
}

/// <summary>
/// The screens a user can open: every active screen of THIS app they hold at least one permission on
/// (from a role, directly assigned screen access, or an override). Never reads hr_payroll's
/// HR_UserMenuRights - the two systems' menu access is separate by design.
/// </summary>
private async Task<List<ListAllMenu>> ResolveUserMenusAsync(HashSet<string>? permissions)
{
    var allMenus = await _menuHandleRepository.FetchAllMenu(null);
    var permissionMenus = permissions == null
        ? new List<ListAllMenu>()
        : allMenus
            .Where(m =>
                m.IsActive == true &&
                !string.IsNullOrEmpty(m.MainMenu) &&
                permissions.Any(p => p.StartsWith($"{m.MainMenu}:", StringComparison.OrdinalIgnoreCase)))
            .ToList();

    return permissionMenus
        .GroupBy(m => (m.NavigateUrl ?? string.Empty).Trim().ToLowerInvariant())
        .Where(g => !string.IsNullOrWhiteSpace(g.Key))
        .Select(g => g.First())
        .OrderBy(m => m.DisplayOrder ?? 0)
        .ThenBy(m => m.MenuId ?? 0)
        .ToList();
}

