		public async Task<IEnumerable<MasterModuleDto>> GetMasterModulesAsync()
		{
			// Using HR_MenuItems.MainMenu as the module identifier. HR_MenuItems is shared with the
			// sibling hr_payroll (ASP.NET WebForms) project - excluded here by NavigateUrl, since
			// every one of its rows ends in ".aspx" (this app's RBAC has nothing to grant against
			// pages it doesn't route to).
			var query = @"SELECT MainMenu AS MenuCode, MenuID AS MenuId, ParentMenu AS MenuCategory
                FROM HR_MenuItems
                WHERE IsActive = 1
                  AND NavigateUrl IS NOT NULL AND NavigateUrl <> '' AND NavigateUrl NOT LIKE '%.aspx%'";

			try
			{
				_logger.LogInformation("Retrieving active master modules from database.");
				var modules = await _context.Connection.QueryAsync<MasterModuleDto>(query);
				_logger.LogInformation("Successfully retrieved {Count} master modules from database.", modules?.Count() ?? 0);
				return modules;
			}
			catch (Exception ex)
