using Microsoft.Extensions.Caching.Memory;
using SolutionOne_BusinessLogicLayer.Services.Common.Interface;
using SolutionOne_BusinessLogicLayer.Services.RBAC.Interface;
using SolutionOne_Core.CommonModels.RBAC;

namespace SolutionOne_BusinessLogicLayer.Services.RBAC.Implementation
{
    public class PermissionChecker : IPermissionChecker
    {
        private static readonly TimeSpan CacheTtl = TimeSpan.FromMinutes(5);

        private readonly IRequestMetadata _requestMetadata;
        private readonly ICurrentUserAccess _access;
        private readonly IPermissionResolver _resolver;
        private readonly IMemoryCache _cache;

        public PermissionChecker(IRequestMetadata requestMetadata, ICurrentUserAccess access, IPermissionResolver resolver, IMemoryCache cache)
        {
            _requestMetadata = requestMetadata;
            _access = access;
            _resolver = resolver;
            _cache = cache;
        }

        public async Task<bool> HasPermissionAsync(string module, string action)
        {
            if (!_requestMetadata.TryGetUserId(out var userId) || userId <= 0)
                return false;

            // Super admin passes everything - including a module with no HR_MenuItems row, which the
            // resolved permission set (built from existing menu x action pairs) could never contain.
            if (await _access.IsAdminAsync())
                return true;

            // Same cache key as PermissionFilter (and evicted by the same RBAC changes), so a role change
            // is honoured by controller-level and service-level checks together.
            var key = PermissionCacheKeys.Permissions((int)userId);
            if (!_cache.TryGetValue(key, out HashSet<string>? permissions) || permissions == null)
            {
                permissions = await _resolver.ResolvePermissionsAsync((int)userId);
                _cache.Set(key, permissions, CacheTtl);
            }

            var required = $"{module}:{action}";
            return permissions.Contains(required, StringComparer.OrdinalIgnoreCase);
        }
    }
}

