import { SettingsFieldOption } from './dashboard-widget.model';
import { normalizeMenuRecord } from '../../../layout/sidenav/menu-tree';
import { isRouteImplemented, normalizeRoute } from '../../../layout/sidenav/implemented-routes';

/**
 * Options for the 'route-picker' field type (Dashboard-Widget-Settings-Schema-Spec.md §8) —
 * built from the SAME rights-filtered menu list already loaded for the sidebar
 * (AuthService.getMenus()), not a dedicated backend endpoint. Backend didn't object to this when
 * the spec proposed it, so this is the frontend's own call, not a confirmed contract detail.
 */
export function buildRouteOptions(menus: Record<string, unknown>[]): SettingsFieldOption[] {
  const seen = new Set<string>();
  const options: SettingsFieldOption[] = [];

  for (const raw of menus ?? []) {
    const menu = normalizeMenuRecord(raw);
    const label = menu.mainMenuText || menu.mainMenu;
    if (!label || !menu.navigateUrl || /^https?:\/\//i.test(menu.navigateUrl)) continue;
    if (!isRouteImplemented(menu.navigateUrl)) continue;

    // normalizeRoute() lowercases/trims for OUR OWN route-matching — using that as the value
    // sent to the backend would mean it no longer matches HR_MenuItems.NavigateUrl's actual
    // stored casing, and GetMenuIdByNavigateUrl silently drops anything it can't resolve (spec
    // §5). Dedupe on the normalized form, but store/send the raw value untouched.
    const dedupeKey = normalizeRoute(menu.navigateUrl);
    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);
    options.push({ value: menu.navigateUrl.trim(), label });
  }

  return options.sort((a, b) => a.label.localeCompare(b.label));
}

